class Solution:
    def mostFrequentIDs(self, nums: List[int], freq: List[int]) -> List[int]:
        cnt = defaultdict(int)
        heap = []
        ans = []
        for x, f in zip(nums, freq):
            cnt[x] += f
            heappush(heap, (-cnt[x], x))
            while heap and -heap[0][0] != cnt[heap[0][1]]:
                heappop(heap)
            ans.append(-heap[0][0] if heap else 0)
        return ans

