from sortedcontainers import SortedList
class Solution:
    def mostFrequentIDs(self, nums: List[int], freq: List[int]) -> List[int]:
        cnt = defaultdict(int)
        sl = SortedList()
        ans = []
        for x, f in zip(nums, freq):
            if cnt[x]: sl.remove(cnt[x])
            cnt[x] += f
            if cnt[x]: sl.add(cnt[x])
            ans.append(sl[-1] if sl else 0)
        return ans

