class Solution {
    public long[] mostFrequentIDs(int[] nums, int[] freq) {
        Map<Integer, Long> cnt = new HashMap<>();
        TreeMap<Long, Integer> ms = new TreeMap<>();
        long[] ans = new long[nums.length];
        for (int i = 0; i < nums.length; i++) {
            long old = cnt.getOrDefault(nums[i], 0L);
            if (old > 0) ms.merge(old, -1, Integer::sum);
            if (ms.get(old) != null && ms.get(old) == 0) ms.remove(old);
            long nw = old + freq[i];
            cnt.put(nums[i], nw);
            if (nw > 0) ms.merge(nw, 1, Integer::sum);
            ans[i] = ms.isEmpty() ? 0 : ms.lastKey();
        }
        return ans;
    }
}

