// JS lacks a built-in ordered multiset; emulate with a lazy max-heap (Approach 1).
var mostFrequentIDs = function(nums, freq) {
    const cnt = new Map();
    const heap = [];
    const push = ([f, id]) => { heap.push([f, id]);
        let i = heap.length - 1;
        while (i > 0) { const p = (i - 1) >> 1;
            if (heap[p][0] >= heap[i][0]) break;
            [heap[p], heap[i]] = [heap[i], heap[p]]; i = p; } };
    const pop = () => { const top = heap[0], last = heap.pop();
        if (heap.length) { heap[0] = last;
            let i = 0;
            for (;;) { const l = 2*i+1, r = l+1; let m = i;
                if (l < heap.length && heap[l][0] > heap[m][0]) m = l;
                if (r < heap.length && heap[r][0] > heap[m][0]) m = r;
                if (m === i) break; [heap[m], heap[i]] = [heap[i], heap[m]]; i = m; } }
        return top; };
    const ans = [];
    for (let i = 0; i < nums.length; i++) {
        cnt.set(nums[i], (cnt.get(nums[i]) || 0) + freq[i]);
        push([cnt.get(nums[i]), nums[i]]);
        while (heap.length && heap[0][0] !== cnt.get(heap[0][1])) pop();
        ans.push(heap.length ? heap[0][0] : 0);
    }
    return ans;
};
